def price(kind, total):
    if kind == "student":
        return total * 0.8
    elif kind == "vip":
        return total * 0.7
    return total

print(price("vip", 100))

class Discount:
    def apply(self, total):
        return total

class Student(Discount):
    def apply(self, total):
        return total * 0.8

class Vip(Discount):
    def apply(self, total):
        return total * 0.7

print(Vip().apply(100))
